// ReactionType defines model for ReactionType.
type ReactionType struct {
	// Access What the viewer's standing against `rule` allows: `open` they may give it, `locked` they may not and the picker shows it greyed, `hidden` they may not and the picker leaves it out. A reaction already given with the type stays and counts whatever this says. The forum limit (`forumIds`) is separate and applies to the item.
	Access ReactionTypeAccess `json:"access"`
	Emoji  string             `json:"emoji"`

	// ForumIds The forums the type may be given in; empty = everywhere. Exactly the forums listed (not their subforums). Content that is not in a forum (profile posts, comments, conversations) counts as elsewhere: the type may be given there only when this list is empty.
	ForumIds []int `json:"forumIds"`

	// Frames How to cut the picture into frames; null for a plain image (the whole picture is the frame) and when there is no picture. A sprite sheet with more than one frame is played as an animation by clients.
	Frames *struct {
		// Columns Frames per row of the picture (its width / `width`).
		Columns int `json:"columns"`

		// Count Frames used, read left to right, then top to bottom.
		Count int `json:"count"`

		// Height Height of one frame in pixels.
		Height int `json:"height"`

		// Width Width of one frame in pixels.
		Width int `json:"width"`
	} `json:"frames"`

	// HideWhenLocked What a member the rule excludes sees: false = the type greyed with a hint (`access` locked), true = the type left out of the picker (`access` hidden).
	HideWhenLocked bool `json:"hideWhenLocked"`
	Id             int  `json:"id"`

	// Image Picture drawn instead of the emoji where pictures can be shown; null when there is none. The emoji stays as the fallback everywhere else.
	Image *struct {
		FileId int    `json:"fileId"`
		Url    string `json:"url"`
	} `json:"image"`
	IsActive bool `json:"isActive"`

	// LockHint In the viewer's language, why a `locked` type is locked (the requirements, phrased from the rule's criteria; a plain "Locked" when the rule is too complex to phrase). Null unless `access` is locked.
	LockHint *string `json:"lockHint"`
	Position int     `json:"position"`

	// Rule Who may give the type, as a rule of cheap criteria (an empty rule is everyone). Criteria that measure the member's history (`measured` in criteria.list) are refused, so the rule costs at most three statements: the member's row, groups and purchases. Only for holders of admin.reactionTypes; null for everyone else.
	Rule  *CriteriaRule `json:"rule"`
	Score int           `json:"score"`
	Title string        `json:"title"`
}

// ReactionTypeAccess What the viewer's standing against `rule` allows: `open` they may give it, `locked` they may not and the picker shows it greyed, `hidden` they may not and the picker leaves it out. A reaction already given with the type stays and counts whatever this says. The forum limit (`forumIds`) is separate and applies to the item.
type ReactionTypeAccess string

